"""FElupe script generated by FElupe Studio (command schema 1)."""

from types import SimpleNamespace

import felupe as fem
import meshio
import numpy as np

# regions by cell type of the solid cells
REGIONS = {
    "tetra": fem.RegionTetra,
    "tetra10": fem.RegionQuadraticTetra,
    "hexahedron": fem.RegionHexahedron,
    "hexahedron20": fem.RegionQuadraticHexahedron,
    "hexahedron27": fem.RegionTriQuadraticHexahedron,
}

# topological dimension of meshio cell types
DIMENSIONS = {
    **dict.fromkeys(["line", "line3"], 1),
    **dict.fromkeys(["triangle", "triangle6", "quad", "quad8", "quad9"], 2),
    **dict.fromkeys(REGIONS, 3),
}


def volume_cells(mesh, tag=None):
    """Return the points, the cell type, the solid cells and their tags (optional) of
    a meshio mesh. Lower-dimensional cell blocks (e.g. boundary faces) are ignored."""
    dim = max(DIMENSIONS.get(block.type, 0) for block in mesh.cells)
    blocks = [i for i, b in enumerate(mesh.cells) if DIMENSIONS.get(b.type) == dim]
    cell_types = {mesh.cells[i].type for i in blocks}
    if dim != 3 or len(cell_types) != 1:
        raise ValueError(f"Expected one type of solid cells, got {cell_types}.")
    cells = np.vstack([mesh.cells[i].data for i in blocks])
    tags = None
    if tag is not None:
        tags = np.concatenate([np.ravel(mesh.cell_data[tag][i]) for i in blocks])
    return SimpleNamespace(
        points=mesh.points, cell_type=cell_types.pop(), cells=cells, tags=tags
    )


# meshes
bar = volume_cells(meshio.read("bar.vtu"), tag="material")

# cell sets
hard = fem.Mesh(bar.points, bar.cells[bar.tags == 1], bar.cell_type)
soft = fem.Mesh(bar.points, bar.cells[bar.tags == 2], bar.cell_type)

# materials
steel_like = fem.LinearElasticLargeStrain(E=10, nu=0.3)
rubber = fem.NeoHooke(mu=1)

# sections: a region and a field container per section
region_hard_body = REGIONS[hard.cell_type](hard)
field_hard_body = fem.FieldContainer([fem.Field(region_hard_body, dim=3)])
region_soft_body = REGIONS[soft.cell_type](soft)
field_soft_body = fem.FieldsMixed(region_soft_body, n=3)

# merge the displacements of all sections into the top-level field
field = fem.field.merge([field_hard_body, field_soft_body])

# solid bodies
solid_hard_body = fem.SolidBody(steel_like, field_hard_body)
solid_soft_body = fem.SolidBody(
    fem.NearlyIncompressible(rubber, bulk=5000), field_soft_body
)

# point sets of the merged mesh
points = field.mesh_container.points
left = np.isclose(points[:, 0], 0, atol=1e-08)
right = np.isclose(points[:, 0], 3, atol=1e-08)

# boundaries
boundaries = {
    "fixed": fem.Boundary(field[0], mask=left),
    "move": fem.Boundary(field[0], mask=right, skip=(0, 1, 1)),
}

# steps
ramp_step_1 = fem.math.linsteps([0, 0.5], num=5)
step_1 = fem.Step(
    items=[solid_hard_body, solid_soft_body],
    ramp={boundaries["move"]: ramp_step_1},
    boundaries=boundaries,
)

# jobs
job_1 = fem.CharacteristicCurve(steps=[step_1], boundary=boundaries["move"])

job_1.evaluate(x0=field)
